using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

/// <summary>
/// MCP tools that wrap the Open-Meteo REST API.
/// The SDK discovers tools by scanning for [McpServerToolType] on the class
/// and [McpServerTool] on each public method.
/// Constructor parameters are resolved from DI automatically.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _http;

    public WeatherTools(HttpClient httpClient)
    {
        _http = httpClient;
    }

    [McpServerTool, Description("Get the current temperature for a location.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true";

        var doc = await _http.GetFromJsonAsync<JsonDocument>(url);
        var weather = doc!.RootElement.GetProperty("current_weather");

        var temp = weather.GetProperty("temperature").GetDouble();
        var windSpeed = weather.GetProperty("windspeed").GetDouble();
        var windDir = weather.GetProperty("winddirection").GetDouble();

        return $"Temperature: {temp}°C, Wind: {windSpeed} km/h from {windDir}°";
    }

    [McpServerTool, Description("Get a multi-day temperature forecast for a location.")]
    public async Task<string> GetForecast(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        [Description("Number of forecast days (1-7)")] int days = 3)
    {
        days = Math.Clamp(days, 1, 7);
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}"
                + $"&daily=temperature_2m_max,temperature_2m_min&forecast_days={days}";

        var doc = await _http.GetFromJsonAsync<JsonDocument>(url);
        var daily = doc!.RootElement.GetProperty("daily");

        var dates = daily.GetProperty("time").EnumerateArray().Select(e => e.GetString()).ToList();
        var maxTemps = daily.GetProperty("temperature_2m_max").EnumerateArray().Select(e => e.GetDouble()).ToList();
        var minTemps = daily.GetProperty("temperature_2m_min").EnumerateArray().Select(e => e.GetDouble()).ToList();

        var lines = dates.Select((d, i) => $"{d}: {minTemps[i]}°C – {maxTemps[i]}°C");
        return string.Join('\n', lines);
    }
}

